import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const b=JSON.parse('{"title":"闲聊近期计划","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/dialogues/05-weekend-plans.md","filePath":"zh/more/maltese/practice/dialogues/05-weekend-plans.md"}'),e={name:"zh/more/maltese/practice/dialogues/05-weekend-plans.md"},i=r('<h1 id="闲聊近期计划" tabindex="-1">闲聊近期计划 <a class="header-anchor" href="#闲聊近期计划" aria-label="Permalink to &quot;闲聊近期计划&quot;">​</a></h1><p><strong>场景：</strong> Anna 和 Mark 聊今天、明天、本周末、下周、下个月及明年的安排。</p><h2 id="完整对话" tabindex="-1">完整对话 <a class="header-anchor" href="#完整对话" aria-label="Permalink to &quot;完整对话&quot;">​</a></h2><p><strong>Anna：</strong> X&#39;għandek tagħmel illum u għada?</p><p><strong>Mark：</strong> Illum naħdem mid-dar u filgħaxija nistudja l-Malti. Għada se mmur l-isptar ma&#39; ommi.</p><p><strong>Anna：</strong> X&#39;se tagħmel fi tmiem il-ġimgħa?</p><p><strong>Mark：</strong> Se niltaqa&#39; mal-ħbieb għal kafè.</p><p><strong>Anna：</strong> Għandek pjanijiet għall-ġimgħa d-dieħla?</p><p><strong>Mark：</strong> Iva. Nhar it-Tlieta se nżur lill-familja tiegħi.</p><p><strong>Anna：</strong> U x-xahar id-dieħel?</p><p><strong>Mark：</strong> Se nivvjaġġa lejn Għawdex għal ftit jiem.</p><p><strong>Anna：</strong> X&#39;tixtieq tagħmel is-sena d-dieħla?</p><p><strong>Mark：</strong> Nixtieq nitgħallem aktar il-Malti u nsiefer.</p><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><h3 id="_1-anna" tabindex="-1">1. Anna <a class="header-anchor" href="#_1-anna" aria-label="Permalink to &quot;1. Anna&quot;">​</a></h3><p><strong>Malti:</strong> X&#39;għandek tagħmel illum u għada?</p><p><strong>整句：</strong> 你今天和明天要做什么？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>X&#39;</td><td>什么</td><td><code>xiex</code> 的缩略形式，常连写在后续词前</td></tr><tr><td>għandek</td><td>你有；你需要</td><td><code>għand</code> 的第二人称单数形式</td></tr><tr><td>tagħmel</td><td>你做</td><td>第二人称单数形式</td></tr><tr><td>illum</td><td>今天</td><td>时间副词</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>għada</td><td>明天</td><td>时间副词</td></tr></tbody></table><h3 id="_2-mark" tabindex="-1">2. Mark <a class="header-anchor" href="#_2-mark" aria-label="Permalink to &quot;2. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Illum naħdem mid-dar u filgħaxija nistudja l-Malti.</p><p><strong>整句：</strong> 今天我在家工作，晚上学习马耳他语。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Illum</td><td>今天</td><td>时间副词</td></tr><tr><td>naħdem</td><td>我工作</td><td>第一人称单数形式</td></tr><tr><td>mid-dar</td><td>从家里；在家</td><td><code>minn</code>“从” + <code>id-dar</code>“家”的缩合形式</td></tr><tr><td>u</td><td>和；并且</td><td>连词</td></tr><tr><td>filgħaxija</td><td>在晚上</td><td>时间表达</td></tr><tr><td>nistudja</td><td>我学习</td><td>第一人称单数形式</td></tr><tr><td>l-Malti</td><td>马耳他语</td><td>语言名称，带定冠词</td></tr></tbody></table><h3 id="_3-mark" tabindex="-1">3. Mark <a class="header-anchor" href="#_3-mark" aria-label="Permalink to &quot;3. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Għada se mmur l-isptar ma&#39; ommi.</p><p><strong>整句：</strong> 明天我会和妈妈去医院。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għada</td><td>明天</td><td>时间副词</td></tr><tr><td>se</td><td>将；会</td><td>常用将来标记</td></tr><tr><td>mmur</td><td>我去</td><td>第一人称单数形式</td></tr><tr><td>l-isptar</td><td>医院</td><td><code>l-</code> 定冠词 + <code>isptar</code></td></tr><tr><td>ma&#39;</td><td>和；与</td><td>介词</td></tr><tr><td>ommi</td><td>我的妈妈</td><td><code>omm</code>“母亲” + 第一人称所有格后缀 <code>-i</code></td></tr></tbody></table><h3 id="_4-anna" tabindex="-1">4. Anna <a class="header-anchor" href="#_4-anna" aria-label="Permalink to &quot;4. Anna&quot;">​</a></h3><p><strong>Malti:</strong> X&#39;se tagħmel fi tmiem il-ġimgħa?</p><p><strong>整句：</strong> 你本周末打算做什么？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>X&#39;</td><td>什么</td><td>疑问词缩略形式</td></tr><tr><td>se</td><td>将；会</td><td>将来标记</td></tr><tr><td>tagħmel</td><td>你做</td><td>第二人称单数形式</td></tr><tr><td>fi</td><td>在</td><td>介词</td></tr><tr><td>tmiem</td><td>结束；末尾</td><td>与后文组成时间短语</td></tr><tr><td>il-ġimgħa</td><td>一周；星期</td><td><code>tmiem il-ġimgħa</code> 整体表示“周末”</td></tr></tbody></table><h3 id="_5-mark" tabindex="-1">5. Mark <a class="header-anchor" href="#_5-mark" aria-label="Permalink to &quot;5. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Se niltaqa&#39; mal-ħbieb għal kafè.</p><p><strong>整句：</strong> 我会和朋友们见面喝咖啡。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Se</td><td>将；会</td><td>将来标记</td></tr><tr><td>niltaqa&#39;</td><td>我见面</td><td>第一人称单数形式；词尾撇号是拼写的一部分</td></tr><tr><td>mal-ħbieb</td><td>和朋友们</td><td><code>ma&#39;</code>“和” + <code>il-ħbieb</code>“朋友们”的缩合形式</td></tr><tr><td>għal</td><td>为了；去做</td><td>此处表示目的</td></tr><tr><td>kafè</td><td>咖啡</td><td>阳性名词；此处指喝咖啡</td></tr></tbody></table><h3 id="_6-anna" tabindex="-1">6. Anna <a class="header-anchor" href="#_6-anna" aria-label="Permalink to &quot;6. Anna&quot;">​</a></h3><p><strong>Malti:</strong> Għandek pjanijiet għall-ġimgħa d-dieħla?</p><p><strong>整句：</strong> 你下周有什么计划吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għandek</td><td>你有</td><td><code>għand</code> 的第二人称单数形式</td></tr><tr><td>pjanijiet</td><td>计划</td><td><code>pjan</code> 的复数</td></tr><tr><td>għall-ġimgħa</td><td>为下周；对于这一周</td><td><code>għal</code> + <code>il-ġimgħa</code> 的缩合形式</td></tr><tr><td>d-dieħla</td><td>接下来的；下一个</td><td>阴性形式，与 <code>ġimgħa</code> 一致</td></tr></tbody></table><h3 id="_7-mark" tabindex="-1">7. Mark <a class="header-anchor" href="#_7-mark" aria-label="Permalink to &quot;7. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Iva. Nhar it-Tlieta se nżur lill-familja tiegħi.</p><p><strong>整句：</strong> 是的。星期二我会去看望我的家人。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Iva</td><td>是；对</td><td>肯定回答</td></tr><tr><td>Nhar</td><td>在……那天</td><td>引出星期或日期</td></tr><tr><td>it-Tlieta</td><td>星期二</td><td>星期名称通常带定冠词</td></tr><tr><td>se</td><td>将；会</td><td>将来标记</td></tr><tr><td>nżur</td><td>我拜访；我看望</td><td>第一人称单数形式</td></tr><tr><td>lill-familja</td><td>家人；我的家人（作宾语）</td><td>人称宾语标记 <code>lil</code> 与定冠词连写</td></tr><tr><td>tiegħi</td><td>我的</td><td>所有格代词</td></tr></tbody></table><h3 id="_8-anna" tabindex="-1">8. Anna <a class="header-anchor" href="#_8-anna" aria-label="Permalink to &quot;8. Anna&quot;">​</a></h3><p><strong>Malti:</strong> U x-xahar id-dieħel?</p><p><strong>整句：</strong> 那下个月呢？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>U</td><td>和；那么</td><td>连接上文，也可引出追问</td></tr><tr><td>x-xahar</td><td>月；这个月</td><td><code>xahar</code>“月”的定冠词形式</td></tr><tr><td>id-dieħel</td><td>下一个；即将到来的</td><td>阳性形式，与 <code>xahar</code> 一致</td></tr></tbody></table><h3 id="_9-mark" tabindex="-1">9. Mark <a class="header-anchor" href="#_9-mark" aria-label="Permalink to &quot;9. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Se nivvjaġġa lejn Għawdex għal ftit jiem.</p><p><strong>整句：</strong> 我下个月会去戈佐岛旅行几天。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Se</td><td>将；会</td><td>将来标记；承接上句的下个月</td></tr><tr><td>nivvjaġġa</td><td>我旅行</td><td>第一人称单数形式</td></tr><tr><td>lejn</td><td>朝向；到</td><td>方向介词</td></tr><tr><td>Għawdex</td><td>戈佐岛</td><td>马耳他群岛中的岛名</td></tr><tr><td>għal</td><td>持续；为期</td><td>此处引出时长</td></tr><tr><td>ftit</td><td>几；少量</td><td>数量词</td></tr><tr><td>jiem</td><td>天</td><td><code>jum</code>“天”的复数形式</td></tr></tbody></table><h3 id="_10-anna" tabindex="-1">10. Anna <a class="header-anchor" href="#_10-anna" aria-label="Permalink to &quot;10. Anna&quot;">​</a></h3><p><strong>Malti:</strong> X&#39;tixtieq tagħmel is-sena d-dieħla?</p><p><strong>整句：</strong> 你明年想做什么？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>X&#39;</td><td>什么</td><td>疑问词缩略形式</td></tr><tr><td>tixtieq</td><td>你想要；你希望</td><td>第二人称单数形式，常用于礼貌询问</td></tr><tr><td>tagħmel</td><td>你做</td><td>第二人称单数形式</td></tr><tr><td>is-sena</td><td>年</td><td><code>sena</code>“年”的定冠词形式</td></tr><tr><td>d-dieħla</td><td>下一个；来临的</td><td>阴性形式，与 <code>sena</code> 一致</td></tr></tbody></table><h3 id="_11-mark" tabindex="-1">11. Mark <a class="header-anchor" href="#_11-mark" aria-label="Permalink to &quot;11. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Nixtieq nitgħallem aktar il-Malti u nsiefer.</p><p><strong>整句：</strong> 我想多学一些马耳他语，也想出国旅行。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nixtieq</td><td>我想要；我希望</td><td>第一人称单数形式</td></tr><tr><td>nitgħallem</td><td>我学习</td><td>第一人称单数形式，词中有 <code>għ</code></td></tr><tr><td>aktar</td><td>更多；进一步</td><td>程度副词</td></tr><tr><td>il-Malti</td><td>马耳他语</td><td>语言名称</td></tr><tr><td>u</td><td>和；并且</td><td>连词</td></tr><tr><td>nsiefer</td><td>我出国旅行</td><td>第一人称单数形式</td></tr></tbody></table><h2 id="时间短语速记" tabindex="-1">时间短语速记 <a class="header-anchor" href="#时间短语速记" aria-label="Permalink to &quot;时间短语速记&quot;">​</a></h2><ul><li><code>illum</code>：今天</li><li><code>għada</code>：明天</li><li><code>fi tmiem il-ġimgħa</code>：本周末</li><li><code>il-ġimgħa d-dieħla</code>：下周</li><li><code>ix-xahar id-dieħel</code>：下个月</li><li><code>is-sena d-dieħla</code>：明年</li></ul>',60),o=[i];function l(n,h,s,g,m,c){return d(),a("div",null,o)}const u=t(e,[["render",l]]);export{b as __pageData,u as default};
